var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
return scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.Renderer>(true)).Where(r=>r.GetComponentInParent<OVRCameraRig>(true)==null && !(r is UnityEngine.SkinnedMeshRenderer) && (r.name.ToLower().Contains("plant")||r.name.ToLower().Contains("pot")||r.name.ToLower().Contains("leaf"))).Select(r=>new{name=r.name,position=r.transform.position.ToString(),active=r.gameObject.activeInHierarchy&&r.enabled,materials=r.sharedMaterials.Where(m=>m!=null).Select(m=>new{name=m.name,shader=m.shader.name,path=UnityEditor.AssetDatabase.GetAssetPath(m)}).ToArray()}).ToArray();
